class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        # Try every possible subarray [i, j] (inclusive)
        for i in range(n):
            for j in range(i, n):
                # Remove subarray from index i to j
                # The remaining array consists of:
                #   - elements before index i (if any)
                #   - elements after index j (if any)

                # Create a new list without the subarray [i, j]
                remaining = []
                if i > 0:
                    remaining.extend(nums[:i])
                if j < n - 1:
                    remaining.extend(nums[j + 1:])

                # Check if remaining is strictly increasing
                is_strictly_increasing = True
                for k in range(1, len(remaining)):
                    if remaining[k] <= remaining[k - 1]:
                        is_strictly_increasing = False
                        break

                if is_strictly_increasing:
                    count += 1

        return count
