class Solution:
    def findMissingAndRepeatedValues(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        total_elements = n * n
        expected_sum = total_elements * (total_elements + 1) // 2
        actual_sum = sum(sum(row) for row in grid)

        # Count frequency of each number
        freq = {}
        for i in range(n):
            for j in range(n):
                num = grid[i][j]
                freq[num] = freq.get(num, 0) + 1

        # Find the repeated number (appears twice)
        repeated = None
        # Find the missing number (should be present but not found)
        missing = None

        for num in range(1, total_elements + 1):
            if freq.get(num, 0) == 2:
                repeated = num
            elif freq.get(num, 0) == 0:
                missing = num

        return [repeated, missing]
