class Solution:
    def findIntersectionValues(self, nums1: List[int], nums2: List[int]) -> List[int]:
        # Convert nums2 to a set for O(1) lookup
        set_nums2 = set(nums2)

        # Count indices in nums1 where nums1[i] exists in nums2
        count1 = 0
        for num in nums1:
            if num in set_nums2:
                count1 += 1

        # Convert nums1 to a set for O(1) lookup
        set_nums1 = set(nums1)

        # Count indices in nums2 where nums2[i] exists in nums1
        count2 = 0
        for num in nums2:
            if num in set_nums1:
                count2 += 1

        return [count1, count2]
