class Solution:
    def areSimilar(self, mat: List[List[int]], k: int) -> bool:
        m, n = len(mat), len(mat[0])

        # For each row, determine the shift direction and apply it k times
        for i in range(m):
            if i % 2 == 1:  # odd indexed row (0-indexed, so index 1,3,5,...)
                # Right cyclic shift k times
                shifts = k % n  # avoid unnecessary full cycles
                if shifts > 0:
                    # Move last 'shifts' elements to front
                    mat[i] = mat[i][-shifts:] + mat[i][:-shifts]
            else:  # even indexed row (0-indexed, so index 0,2,4,...)
                # Left cyclic shift k times
                shifts = k % n
                if shifts > 0:
                    # Move first 'shifts' elements to end
                    mat[i] = mat[i][shifts:] + mat[i][:shifts]

        # Compare modified matrix with original
        return mat == [[row[j] for j in range(n)] for row in mat]

