class Solution:
    def findMinimumOperations(self, s1: str, s2: str, s3: str) -> int:
        # If any string is empty, we cannot make them equal unless all are empty
        if len(s1) == 0 or len(s2) == 0 or len(s3) == 0:
            return -1 if not (len(s1) == 0 and len(s2) == 0 and len(s3) == 0) else 0

        # Check if the first characters are the same
        if s1[0] != s2[0] or s2[0] != s3[0] or s1[0] != s3[0]:
            return -1

        # Find the maximum length we can keep for all strings
        # We need to find the longest common prefix among all three strings
        min_len = min(len(s1), len(s2), len(s3))
        common_prefix_length = 0

        for i in range(min_len):
            if s1[i] == s2[i] == s3[i]:
                common_prefix_length += 1
            else:
                break

        # If there's no common prefix, we cannot make them equal
        if common_prefix_length == 0:
            return -1

        # Total operations needed
        operations = (len(s1) - common_prefix_length) + (len(s2) - common_prefix_length) + (len(s3) - common_prefix_length)

        return operations
