class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0
        n = len(nums)

        # Check all pairs (including same element twice)
        for i in range(n):
            for j in range(n):
                x, y = nums[i], nums[j]
                # Check if the pair is strong
                if abs(x - y) <= min(x, y):
                    # Update maximum XOR if current pair satisfies strong condition
                    current_xor = x ^ y
                    max_xor = max(max_xor, current_xor)

        return max_xor
