class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        count = 0
        # Iterate over possible candies for first child
        for a in range(min(n, limit) + 1):
            # Iterate over possible candies for second child
            for b in range(min(n - a, limit) + 1):
                # Calculate candies for third child
                c = n - a - b
                # Check if third child's candies are within limit and non-negative
                if 0 <= c <= limit:
                    count += 1
        return count
