class Solution:
    def findChampion(self, grid: List[List[int]]) -> int:
        n = len(grid)
        # Find the team that has no other team stronger than it
        # That is, for team i, there should be no j such that grid[j][i] == 1
        for i in range(n):
            is_champion = True
            for j in range(n):
                if j != i and grid[j][i] == 1:
                    is_champion = False
                    break
            if is_champion:
                return i
        return -1  # This should never happen given the constraints
