class Solution:
    def findKOr(self, nums: List[int], k: int) -> int:
        result = 0

        # Check each bit position from 0 up to the maximum possible bit (31 since nums[i] < 2^31)
        for bit in range(32):
            count = 0
            # Count how many numbers in nums have this bit set
            for num in nums:
                if num & (1 << bit):
                    count += 1

            # If at least k numbers have this bit set, set the bit in the result
            if count >= k:
                result |= (1 << bit)

        return result
