class Solution:
    def lastVisitedIntegers(self, words: List[str]) -> List[int]:
        result = []
        nums = []  # to store integers seen so far
        consecutive_prev = 0  # count of consecutive "prev" strings

        for word in words:
            if word == "prev":
                # For "prev", we need to find the last visited integer based on consecutive count
                consecutive_prev += 1
                if consecutive_prev <= len(nums):
                    # The last visited integer is at (consecutive_prev - 1)th index from the end of nums
                    result.append(nums[-consecutive_prev])
                else:
                    # If more consecutive "prev"s than integers seen, return -1
                    result.append(-1)
            else:
                # It's a number string, add it to nums and reset consecutive_prev to 0
                nums.append(int(word))
                consecutive_prev = 0

        return result
