    def sumIndicesWithKSetBits(self, nums: List[int], k: int) -> int:
        total = 0
        for i in range(len(nums)):
            # Count the number of set bits in index i
            count = 0
            temp = i
            while temp > 0:
                count += temp & 1
                temp >>= 1
            # If the count equals k, add the corresponding element to total
            if count == k:
                total += nums[i]
        return total
