from typing import List

class Solution:
    def isGood(self, nums: List[int]) -> bool:
        n = len(nums)
        max_val = max(nums)

        # The array must be a permutation of base[n], so:
        # 1. The maximum value must be n (since base[n] ends with n twice)
        # 2. The length of nums must be n + 1 (since base[n] has n+1 elements)
        # 3. All numbers from 1 to n-1 must appear exactly once
        # 4. The number n must appear exactly twice

        if max_val != n or n != len(nums):
            return False

        # Count frequency of each number
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1

        # Check that numbers 1 to n-1 appear exactly once
        for i in range(1, n):
            if freq.get(i, 0) != 1:
                return False

        # Check that n appears exactly twice
        if freq.get(n, 0) != 2:
            return False

        return True
