class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        max_length = -1

        # Try starting at each position
        for i in range(n - 1):
            # Check if we can start an alternating subarray at index i
            if nums[i + 1] == nums[i] + 1:
                current_length = 2
