class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        max_length = -1

        # Try starting at each position
        for i in range(n - 1):
            # Check if we can start an alternating subarray at index i
            if nums[i + 1] == nums[i] + 1:
                current_length = 2
                valid = True

                # Extend the subarray as long as it remains alternating
                for j in range(i + 2, n):
                    expected_diff = 1 if (j - i) % 2 == 1 else -1
                    if nums[j] != nums[j - 1] + expected_diff:
                        break
                    current_length += 1

                # Update max_length if this subarray is longer
                if current_length > max_length:
                    max_length = current_length

        return max_length

