class Solution:
    def longestAlternatingSubarray(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        max_length = 0

        # Try starting at each index
        for l in range(n):
            # Check if current element is even and <= threshold
            if nums[l] % 2 == 0 and nums[l] <= threshold:
                current_length = 1
                valid = True

                # Extend the subarray as long as conditions are met
                for r in range(l + 1, n):
                    # Check if current element is <= threshold
                    if nums[r] > threshold:
                        break

                    # Check alternating parity condition
                    if nums[r] % 2 == nums[r - 1] % 2:
                        break

                    current_length += 1

                max_length = max(max_length, current_length)

        return max_length
