class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        n = len(nums)
        if n <= 1:
            return True

        # Helper function to count set bits
        def count_set_bits(x):
            count = 0
            while x:
                count += x & 1
                x >>= 1
            return count

        # Group elements by their set bit count
        groups = []
        current_group = [nums[0]]
        current_bit_count = count_set_bits(nums[0])

        for i in range(1, n):
            bit_count = count_set_bits(nums[i])
            if bit_count == current_bit_count:
                current_group.append(nums[i])
            else:
                groups.append(current_group)
                current_group = [nums[i]]
                current_bit_count = bit_count

        groups.append(current_group)

        # Check if each group is sorted internally
        for group in groups:
            if group != sorted(group):
                return False

        # Check if the last element of each group is <= the first element of the next group
        for i in range(len(groups) - 1):
            if groups[i][-1] > groups[i + 1][0]:
                return False

        return True
