class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        # Dictionary to store frequency of each special substring length for each character
        char_freq = defaultdict(list)

        # Find all consecutive runs of the same character
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]:
                j += 1
            length = j - i
            # For a run of length 'length', we can form special substrings of lengths 1, 2, ..., length
            # Each length k can be formed (length - k + 1) times in this run
            for k in range(1, length + 1):
                count = length - k + 1
                if count >= 3:  # Only consider if it occurs at least thrice
                    char_freq[s[i]].append((k, count))
            i = j

        max_length = -1

        # Check each character's possible special substrings
        for char, freq_list in char_freq.items():
            for length, count in freq_list:
                if count >= 3:
                    max_length = max(max_length, length)

        return max_length

