class Solution:
    def largestPerimeter(self, nums: List[int]) -> int:
        nums.sort()
        total = sum(nums)
        n = len(nums)

        # Start from the largest possible polygon (using as many sides as possible)
        # Check from the end backwards: if the sum of all previous sides > current side,
        # then we can form a polygon with these sides.
        for i in range(n - 1, 1, -1):  # i goes from last index down to index 2 (since we need at least 3 sides)
            if total - nums[i] > nums[i]:
                return total
            total -= nums[i]

        return -1

