class Solution:
    def getGoodIndices(self, variables: List[List[int]], target: int) -> List[int]:
        good_indices = []

        for i in range(len(variables)):
            a, b, c, m = variables[i]

            # Calculate (a^b % 10)
            inner_mod = pow(a, b, 10)

            # Calculate ((a^b % 10)^c) % m
            result = pow(inner_mod, c, m)

            # Check if it equals target
            if result == target:
                good_indices.append(i)

        return good_indices

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        max_val = max(nums)
        n = len(nums)
        count = 0

        # For each starting position
        for i in range(n):
            freq = 0
            # Extend subarray from position i
            for j in range(i, n):
                if nums[j] == max_val:
                    freq += 1
                # If we have at least k occurrences of max_val, all subarrays ending at j and starting from i to j are valid
                if freq >= k:
                    count += (n - j)
                    break

        return count

