class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        count = 0
        # Iterate over possible values for the first child
        for a in range(min(n + 1, limit + 1)):
            remaining = n - a
            # Iterate over possible values for the second child
            for b in range(min(remaining + 1, limit + 1)):
                c = remaining - b
                # Check if the third child's candies are valid
                if 0 <= c <= limit:
                    count += 1
        return count

