class Solution:
    def findChampion(self, n: int, edges: List[List[int]]) -> int:
        # Count the number of incoming edges for each team
        in_degree = [0] * n

        for u, v in edges:
            in_degree[v] += 1

        # Find teams with zero incoming edges (champions)
        champions = []
        for i in range(n):
            if in_degree[i] == 0:
                champions.append(i)

        # Return the champion if unique, otherwise return -1
        return champions[0] if len(champions) == 1 else -1

