class Solution:
    def minChanges(self, s: str) -> int:
        changes = 0
        # Iterate through the string two characters at a time
        for i in range(0, len(s), 2):
            # If the two characters are different, we need to change one of them
            if s[i] != s[i + 1]:
                changes += 1
        return changes
