from typing import List

class Solution:
    def lengthOfLongestSubsequence(self, nums: List[int], target: int) -> int:
        n = len(nums)
        # dp[i][j] represents the maximum length of subsequence using first i elements that sums to j
        # Initialize with -1 (impossible)
        dp = [[-1] * (target + 1) for _ in range(n + 1)]

        # Base case: empty subsequence has sum 0 and length 0
        for i in range(n + 1):
            dp[i][0] = 0

        # Fill the dp table
        for i in range(1, n + 1):
            for j in range(target + 1):
                # Don't take nums[i-1]
                dp[i][j] = dp[i-1][j]

                # Take nums[i-1] if possible
                if j >= nums[i-1]:
                    if dp[i-1][j - nums[i-1]] != -1:
                        dp[i][j] = max(dp[i][j], dp[i-1][j - nums[i-1]] + 1)

        return dp[n][target]
