completion:
class Solution:
    def maxSubarrays(self, nums: List[int]) -> int:
        total_and = nums[0]
        for i in range(1, len(nums)):
            total_and &= nums[i]

        # If total AND is 0, we can split into multiple subarrays
        # The goal is to maximize the number of subarrays while keeping the total score minimum (which is total_and)
        if total_and == 0:
            count = 0
            current_and = nums[0]
            for i in range(len(nums)):
                current_and &= nums[i]
                if current_and == 0:
                    count += 1
                    current_and = -1  # mark as reset, but actually we need to start fresh from next element
                    if i < len(nums) - 1:
                        current_and = nums[i + 1] if i + 1 < len(nums) else 0
                    else:
                        break
            return count

        # If total AND != 0, then we cannot split further without increasing the total score
        # So we must keep everything together
        return 1

