class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        n = len(nums)
        # If array has only 1 or 2 elements, it's always possible to split into n arrays
        if n <= 2:
            return True

        # Try all possible splits recursively or use dynamic programming
        # We'll use memoization to avoid recomputation

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dfs(start, end):
            # Base case: single element subarray is always valid
            if start == end:
                return True

            # Try all possible splits within [start, end]
            for i in range(start + 1, end + 1):
                # Split into [start, i-1] and [i, end]
                left_sum = sum(nums[start:i])
                right_sum = sum(nums[i:end + 1])

                # Check if both parts satisfy the condition
                left_valid = (i - start == 1) or (left_sum >= m)
                right_valid = (end - i + 1 == 1) or (right_sum >= m)

                if left_valid and right_valid:
                    # Recursively check if both parts can be further split
                    if dfs(start, i - 1) and dfs(i, end):
                        return True

            return False

        return dfs(0, n - 1)

