```python
class Solution:
    def sortVowels(self, s: str) -> str:
        vowels = set('aeiouAEIOU')
        vowel_list = []

        # Extract all vowels from the string
        for char in s:
            if char in vowels:
                vowel_list.append(char)

        # Sort the vowels by ASCII value
        vowel_list.sort()

        # Build result string: consonants stay in place, vowels are replaced in sorted order
        result = []
        vowel_index = 0

        for char in s:
            if char in vowels:
                result.append(vowel_list[vowel_index])
                vowel_index += 1
            else:
                result.append(char)

        return ''.join(result)
