from typing import List

class Solution:
    def maximumJumps(self, nums: List[int], target: int) -> int:
        n = len(nums)
        # dp[i] represents the maximum number of jumps to reach index i
        dp = [-1] * n  # Initialize with -1 meaning unreachable
        dp[0] = 0      # Starting at index 0, 0 jumps needed

        # Iterate through each index
        for i in range(n):
            if dp[i] == -1:
                continue  # Skip if current index is unreachable

            # Try to jump from index i to all possible j > i
            for j in range(i + 1, n):
                # Check if we can jump from i to j
                if -target <= nums[j] - nums[i] <= target:
                    # Update dp[j] if we can reach j with more jumps
                    if dp[j] == -1:
                        dp[j] = dp[i] + 1
                    else:
                        dp[j] = max(dp[j], dp[i] + 1)

        return dp[n - 1]
