class Solution:
    def maxNonDecreasingLength(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        # dp[i][0] represents the length of longest non-decreasing subarray ending at index i if we choose nums1[i]
        # dp[i][1] represents the length of longest non-decreasing subarray ending at index i if we choose nums2[i]
        dp = [[1, 1] for _ in range(n)]

        for i in range(1, n):
            # Try choosing nums1[i]
            if nums1[i] >= nums1[i-1]:
                dp[i][0] = max(dp[i][0], dp[i-1][0] + 1)
            if nums1[i] >= nums2[i-1]:
                dp[i][0] = max(dp[i][0], dp[i-1][1] + 1)

            # Try choosing nums2[i]
            if nums2[i] >= nums1[i-1]:
                dp[i][1] = max(dp[i][1], dp[i-1][0] + 1)
            if nums2[i] >= nums2[i-1]:
                dp[i][1] = max(dp[i][1], dp[i-1][1] + 1)

        return max(max(dp[i][0], dp[i][1]) for i in range(n))

