class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        # Helper function to check if a binary string is beautiful
        def is_beautiful(binary_str):
            # Check for leading zeros
            if len(binary_str) > 1 and binary_str[0] == '0':
                return False
            # Convert binary string to integer
            num = int(binary_str, 2)
            # Check if it's a power of 5
            temp = 1
            while temp < num:
                temp *= 5
            return temp == num

        # Memoization dictionary to avoid recomputing
        memo = {}

        def dp(start):
            if start == len(s):
                return 0

            if start in memo:
                return memo[start]

            min_partitions = float('inf')

            # Try all possible ending positions for the current substring
            for end in range(start + 1, len(s) + 1):
                substring = s[start:end]
                if is_beautiful(substring):
                    remaining_partitions = dp(end)
                    if remaining_partitions != -1:  # Only proceed if remaining can be partitioned
                        min_partitions = min(min_partitions, 1 + remaining_partitions)

            memo[start] = min_partitions if min_partitions != float('inf') else -1
            return memo[start]

        result = dp(0)
        return result

from typing import List

class Solution:
    def countBlackBlocks(self, m: int, n: int, coordinates: List[List[int]]) -> List[int]:
        # Dictionary to store the count of black cells for each block
        # Key: (top_left_x, top_left_y) of the block
        # Value: number of black cells in that block
        block_count = {}

        # Set of all black cell coordinates for O(1) lookup
        black_cells = set()
        for x, y in coordinates:
            black_cells.add((x, y))

        # Iterate through all possible 2x2 blocks
        for x in range(m - 1):
            for y in range(n - 1):
                # Count black cells in this block
                count = 0
                for dx in range(2):  # 0 and 1
                    for dy in range(2):  # 0 and 1
                        if (x + dx, y + dy) in black_cells:
                            count += 1

                # Store the count for this block
                block_count[(x, y)] = count

        # Initialize result array for counts of blocks with exactly i black cells
        result = [0] * 5

        # Count how many blocks have exactly i black cells
        for count in block_count.values():
            if count < 5:
                result[count] += 1

        return result

