class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0

        # Helper function to check if array is strictly increasing
        def is_strictly_increasing(arr):
            for i in range(1, len(arr)):
                if arr[i] <= arr[i-1]:
                    return False
            return True

        # Try every possible subarray [i, j] (inclusive) and check if removing it makes the rest strictly increasing
        for i in range(n):
            for j in range(i, n):
                # Remove subarray from index i to j (inclusive)
                # The remaining parts are: [0, i-1] and [j+1, n-1]
                left_part = nums[:i]
                right_part = nums[j+1:]

                # Combine the two parts
                combined = left_part + right_part

                # Check if combined is strictly increasing
                if is_strictly_increasing(combined):
                    total += 1

        return total

