```python
from typing import List
import itertools
import heapq

class Solution:
    def numberOfSets(self, n: int, maxDistance: int, roads: List[List[int]]) -> int:
        # Build adjacency list for the graph
        graph = [[] for _ in range(n)]
        for u, v, w in roads:
            graph[u].append((v, w))
            graph[v].append((u, w))

        def floyd_warshall():
            # Initialize distance matrix with infinity
            dist = [[float('inf')] * n for _ in range(n)]
            for i in range(n):
                dist[i][i] = 0

            # Add direct edges
            for u, v, w in roads:
                dist[u][v] = min(dist[u][v], w)
                dist[v][u] = min(dist[v][u], w)

            # Floyd-Warshall algorithm
            for k in range(n):
                for i in range(n):
                    for j in range(n):
                        if dist[i][k] + dist[k][j] < dist[i][j]:
                            dist[i][j] = dist[i][k] + dist[k][j]

            return dist

        # Compute all pairs shortest paths
        dist = floyd_warshall()

        count = 0

        # Try all possible subsets of branches to close (2^n possibilities)
        for mask in range(1 << n):
            active_branches = []
            for i in range(n):
                if not (mask & (1 << i)):  # branch i is active
                    active_branches.append(i)

            # If no active branches, it's valid
            if len(active_branches) == 0:
                count += 1
                continue

            # Check if all pairs of active branches are within maxDistance
            valid = True
            for i in range(len(active_branches)):
                for j in range(i + 1, len(active_branches)):
                    u, v = active_branches[i], active_branches[j]
                    if dist[u][v] > maxDistance:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                count += 1

        return count
```

The solution uses Floyd-Warshall algorithm to compute all-pairs shortest paths between branches. Then, it tries all possible subsets of branches to close (using bitmasks from 0 to 2^n - 1). For each subset, it checks whether the remaining active branches are all within maxDistance of each other. If yes, it increments the count.

Time complexity: O(2^n * n^2) for trying all subsets and checking distances.
Space complexity: O(n^2) for storing the distance matrix.

