class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0
        n = len(nums)

        # Check all pairs (including same element twice)
        for i in range(n):
            for j in range(n):
                x, y = nums[i], nums[j]
                # Check if the pair is strong: |x - y| <= min(x, y)
                if abs(x - y) <= min(x, y):
                    current_xor = x ^ y
                    max_xor = max(max_xor, current_xor)

        return max_xor

