class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Convert forbidden list to a set for O(1) lookup
        forbidden_set = set(forbidden)

        max_length = 0
        n = len(word)

        # For each possible starting position of substring
        for i in range(n):
            # Check all substrings starting at position i
            # We only need to check up to length 10 since forbidden strings are at most length 10
            for j in range(i + 1, min(i + 11, n + 1)):
                substring = word[i:j]
                if substring in forbidden_set:
                    break
            else:
                # If we didn't break, then substring from i to j-1 is valid
                max_length = max(max_length, j - i)

        return max_length

